const $=s=>document.querySelector(s);let notes=[],savedAnswers={};let storageOK=true;try{notes=JSON.parse(localStorage.getItem('muguang-notes')||'[]');if(!Array.isArray(notes))notes=[];savedAnswers=JSON.parse(localStorage.getItem('muguang-answers')||'{}');if(!savedAnswers||typeof savedAnswers!=='object')savedAnswers={}}catch{storageOK=false;notes=[];savedAnswers={}}let current=0,selected=null,sessionAnswers={},startIndex=0;
const lessons=[
{principle:'对比',title:'谁应该先被看见？',brief:'你第一次收到这张名片，需要快速记住对方是谁。哪张名片的信息层级更清楚？',type:'card',bad:'bad-contrast',labels:['所有信息，差不多大','让姓名成为第一眼的重点'],correct:1,why:'B 用字号与字重拉开姓名和联系方式的差距，视线先停在「陈默」，再读取职业，最后找到联系信息。A 的每一行都在用相近的音量说话，读者需要自己寻找重点。',rule:'对比：先确定唯一的首要信息，再拉开层级。不是所有元素都需要更大、更亮。',tip:'先说清这一屏最希望用户记住什么。把它放到第一层，其余信息降到第二、第三层。'},
{principle:'重复',title:'统一，为什么让人更信任？',brief:'名片需要表达克制、专业的品牌气质。哪一版的视觉语言更一致？',type:'card',bad:'bad-repeat',labels:['每种信息，都换一种风格','延续同一套字体与字重规则'],correct:1,why:'B 让字体、字重和间距遵循相同规则，读者更容易把信息识别为同一个品牌。A 的联系方式突然更换字体与颜色，增加了没有意义的差异。',rule:'重复：让相同职责的信息，遵循相同的视觉规则。统一之后，有目的的变化才更突出。',tip:'从品牌字体、圆角、按钮和标题样式入手复用规则。活动可以有变化，但不能让每个元素都重新发明一套语言。'},
{principle:'亲密',title:'距离，也在表达关系。',brief:'这里的「亲密」指接近性。同一个人的姓名、职业、联系方式，怎样安排才更容易理解？',type:'card',bad:'bad-proximity',labels:['平均分配，铺满四个角落','相关信息靠近，不同组留白'],correct:1,why:'B 把姓名与职业组成身份组，联系方式组成联络组。读者先理解关系，再读取细节。A 把相关内容分散，虽然空间分配均匀，却增加了寻找与配对的成本。',rule:'亲密：相关的靠近，不相关的拉开。空白不只是空出来的地方，它在帮助信息分组。',tip:'把优惠金额与使用条件放成一个信息组。不要把关键门槛拆到资源位边缘，让用户点击后才发现。'},
{principle:'对齐',title:'看不见的线，让信息站稳。',brief:'内容、字号和颜色相同。哪一版的阅读路径更稳定？',type:'card',bad:'bad-align',labels:['每一组，都有自己的起点','沿一条明确的左边线组织'],correct:1,why:'B 的品牌、身份和联络信息共享左侧基准，视线有一条稳定的回归线。A 同时使用左、中、右对齐，缺少能解释这种变化的信息关系。',rule:'对齐：每个元素都应与另一个元素建立明确的视觉关系。居中也可以成立，关键是有规则。',tip:'先找页面现有的内容边界与栅格。让资源位的文案与按钮共享基准，不靠目测随意摆放。'},
{principle:'场景与调性',title:'吸引注意，也要属于这里。',brief:'教学模拟：一款以周末生活灵感为主的 APP，要推荐附近散步路线。哪张资源图更适合这个场景？',type:'resource',labels:['延续页面语气，让主张清楚','增加颜色、边框和大字抢注意'],correct:0,why:'A 延续页面的色彩、字重与留白，把「周末散步」作为清楚的主张。B 的强刺激样式会打断轻松浏览的节奏。强对比本身没有错，但需要服务于品牌和当前任务。',rule:'资源位的好坏，要放回它出现的页面判断。独立吸睛，不等于整体体验合适。',tip:'把资源图放进真实页面，连同上下模块一起看。检查它的视觉音量是否盖过了用户当前任务。'},
{principle:'信息层级',title:'优惠信息，先讲哪一句？',brief:'教学模拟：咖啡券活动仅限新用户，领券后需满 30 元使用。哪种表达更方便用户做决定？',type:'offer',labels:['免费喝咖啡！点击再看条件','新客领 10 元券，满 30 元可用'],correct:1,why:'B 同时给出利益、身份门槛和使用条件，让用户在点击前判断是否与自己相关。A 把「免费」当作吸引力，却没有兑现这个承诺，容易造成落差。',rule:'先明确利益，再交代影响决策的条件。层级清晰不能以隐藏限制为代价。',tip:'把「谁能用、能得到什么、要满足什么」写在一起，再通过字号与间距分出主次。'},
{principle:'用户路径',title:'点进去的那一刻，承诺兑现了吗？',brief:'教学模拟：资源位写着「附近免费展览」。哪条路径更尊重用户已经形成的预期？',type:'path',labels:['进入品牌首页，再自行寻找展览','直达附近免费展览列表'],correct:1,why:'B 承接了资源位的地点、价格与内容承诺。A 虽然可能最终也能找到展览，但用户需要重新理解导航、重新搜索，资源位建立的期待被中断。',rule:'检查完整路径：看见什么 → 以为什么 → 点击哪里 → 实际得到什么。每一步都应承接上一步。',tip:'审核时亲自点一次。核对标题、内容、优惠资格与到达页面，尤其关注返回和空结果状态。'},
{principle:'协作表达',title:'把「不够高级」，变成可行动的建议。',brief:'教学模拟：一个活动资源位有三个同样醒目的标题。哪条反馈更能帮助运营和设计师共同改进？',type:'critique',labels:['缺少高级感，能不能再有设计感一点？','先突出主利益，弱化副标题和装饰'],correct:1,why:'B 指明了问题、目标和动作：三个重点竞争注意力，先选出一个主利益，再降低其他元素的视觉音量。A 表达了感受，但没有建立可讨论的判断依据。',rule:'有效反馈 = 用户任务 + 可观察的问题 + 建议的调整。最后用真实页面验证是否改善。',tip:'可以这样说：「用户需要先知道优惠是什么。目前三个标题一样大，建议主利益保留最大字号，时间与说明降一级。」'}];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageOK=false;return false}}function updateCount(){$('#note-count').textContent=notes.length}updateCount();
function sample(q,i){if(q.type==='card')return `<div class="sample-card ${i===q.correct?'good':q.bad}"><div class="studio">LINJIAN DESIGN STUDIO</div><div><div class="name">陈默</div><div class="position">品牌设计师</div></div><div class="contact">hello@linjian.studio<br>138 0000 2026</div></div>`;if(q.type==='resource'||q.type==='offer'){const good=i===q.correct;const offer=q.type==='offer';return `<div class="resource-demo"><div class="app-bar"><b>生活灵感</b><span>附近　收藏</span></div><div class="resource-banner ${good?'':'loud'}"><strong>${offer?(good?'新客，来杯好咖啡。':'免费喝咖啡！'):(good?'周末，走慢一点。':'周末必去！立即出发！')}</strong><p>${offer?(good?'领 10 元咖啡券 · 满 30 元可用':'超值福利！限时抢！'):(good?'发现附近的 3 条散步路线':'发现宝藏路线！错过再等一年！')}</p><span>${offer?'去领券 →':'探索散步路线 →'}</span></div><div class="app-placeholder"><i></i><i></i><i></i></div></div>`}if(q.type==='path')return `<div class="path-sample"><div><small>用户看见</small>附近免费展览 →</div><span>↓</span><div><small>点击后抵达</small>${i===1?'附近免费展览列表 · 默认按距离排序':'品牌首页 · 商城 / 动态 / 会员 / 更多'}</div></div>`;return `<div class="path-sample"><div><small>给设计同事的反馈</small>${esc(q.labels[i])}</div><div><small>下一步</small>${i===1?'选出主利益，调整字号，再放回页面检验。':'设计师需要继续追问：「具体指哪里？」'}</div></div>`}
function begin(index){window.RefineMetrics?.start(index);current=index;startIndex=index;selected=null;sessionAnswers={};$('#training').showModal();render();}document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>begin(+b.dataset.start));$('#exit').onclick=()=>$('#training').close();
function render(){const q=lessons[current];$('#exercise-progress').textContent=`${String(current+1).padStart(2,'0')} / 08 · ${q.principle}`;$('#exercise').innerHTML=`<div class="exercise-heading"><span class="section-kicker">${current<4?'从一张名片开始':current<6?'把原则带回页面':'从点击前，到抵达后'}</span><h2 id="exercise-title">${q.title}</h2><p>${q.brief}</p></div><div class="options">${q.labels.map((label,i)=>`<button class="option" data-option="${i}" aria-label="选项 ${i===0?'A':'B'}：${esc(label)}">${sample(q,i)}<div class="option-label"><span class="letter">${i===0?'A':'B'}</span>${label}</div></button>`).join('')}</div><div id="feedback-slot" aria-live="polite"></div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>answer(+b.dataset.option));$('#training').scrollTop=0;$('#exercise-title').setAttribute('tabindex','-1');$('#exercise-title').focus({preventScroll:true});}
function answer(i){if(selected!==null)return;selected=i;window.RefineMetrics?.send('answer',{q:current,choice:i});const q=lessons[current];sessionAnswers[current]=i;savedAnswers[current]=i;persist('muguang-answers',savedAnswers);document.querySelectorAll('[data-option]').forEach(b=>{b.disabled=true;b.classList.toggle('selected',+b.dataset.option===i);b.classList.toggle('correct',+b.dataset.option===q.correct)});$('#feedback-slot').innerHTML=`<div class="feedback"><h3>${i===q.correct?'你看见了关键。':'再看一次信息之间的关系。'}</h3><p>${q.why}</p><p><b>${q.rule}</b></p><details class="coach"><summary>再聊深一点</summary><div class="coach-buttons"><button data-coach="0">用大白话再讲一次</button><button data-coach="1">怎么用在资源位里？</button><button data-coach="2">有没有例外？</button></div><p class="coach-answer" aria-live="polite"></p><small>当前为课程预设讲解，尚未连接语言模型。</small></details><div class="reflection"><label for="reflection">用自己的话，说一句改进建议（选填）</label><textarea id="reflection" maxlength="1500" placeholder="例如：先明确用户第一眼要看见什么，再拉开主标题与说明的字号。"></textarea><div class="save-row"><button class="secondary" id="save-note">记下这个发现 ＋</button><span class="save-status" role="status"></span></div></div><div class="feedback-actions"><span class="section-kicker">${q.principle} · 看见理由</span><button class="primary" id="next">${current===7?'查看学习回顾':'下一练'} <span>→</span></button></div></div>`;document.querySelectorAll('[data-coach]').forEach(b=>b.onclick=()=>{const responses=[q.rule+' 可以先遮住细节，看看第一眼留下的是什么。',q.tip,'这些原则是判断工具，不是固定答案。海报可以密集、可以居中，也可以有强烈变化；需要看它是否服务于当前的用户任务，并能解释每一个取舍。'];$('.coach-answer').textContent=responses[+b.dataset.coach]});$('#save-note').onclick=()=>saveNote(q);$('#next').onclick=()=>{if(current===7)result();else{current++;selected=null;render()}};}
function saveNote(q){const value=$('#reflection').value.trim();if(!value){$('.save-status').textContent='先写下一句你的观察。';$('#reflection').focus();return}window.RefineMetrics?.send('note_saved');notes.push({topic:q.principle,text:value,date:new Date().toLocaleDateString('zh-CN')});const ok=persist('muguang-notes',notes);updateCount();$('.save-status').textContent=ok?'已保存到我的笔记。':'浏览器无法保存，请在关闭页面前导出笔记。';$('#save-note').disabled=true;$('#reflection').addEventListener('input',()=>{$('#save-note').disabled=false;$('.save-status').textContent=''},{once:true})}
function result(){window.RefineMetrics?.send('complete');const entries=Object.entries(sessionAnswers);const correct=entries.filter(([j,a])=>lessons[j].correct===a).length;const review=entries.filter(([j,a])=>lessons[j].correct!==a).map(([j])=>lessons[j].principle);$('#exercise-progress').textContent='学习回顾';$('#exercise').innerHTML=`<div class="result"><span class="section-kicker">A BETTER WAY OF SEEING</span><h2 id="exercise-title">让直觉，慢慢有依据。</h2><div class="result-count">${correct}<small> / ${entries.length} 个判断</small></div><p>这是这次练习的回顾，不是审美能力的评分。<br>能说清为什么，就是一次进步。</p><div class="result-principles">${['对比','重复','亲密','对齐'].map(t=>`<span>${t}</span>`).join('')}</div>${review.length?`<p class="result-review">可以再观察：${review.join('、')}。换一个场景，再试着解释你的判断。</p>`:'<p>下一次审核资源位时，试着走完「看见、点击、抵达」这条路径。</p>'}<div class="result-actions"><button class="primary" id="retry">再练一次 <span>↗</span></button><button class="secondary" id="result-notes">查看我的笔记</button><button class="secondary" id="result-home">回到练习室</button></div></div>`;$('#retry').onclick=()=>{window.RefineMetrics?.start(0);current=0;selected=null;sessionAnswers={};render()};$('#result-notes').onclick=openNotes;$('#result-home').onclick=()=>$('#training').close();$('#training').scrollTop=0;}
function openNotes(){$('#notes-list').innerHTML=notes.length?notes.map(n=>`<article class="note-item"><small>${esc(n.date)} · ${esc(n.topic)}</small><p>${esc(n.text)}</p></article>`).join(''):'<div class="empty">还没有留下观察。<br>完成一道练习，写下你的第一条改进建议。</div>';$('#export-notes').disabled=!notes.length;$('#notebook').showModal()}$('#notes-open').onclick=openNotes;$('#notebook-in').onclick=openNotes;$('#notes-close').onclick=()=>$('#notebook').close();$('#export-notes').onclick=()=>{const text='目光 · 我的设计观察\n\n'+notes.map(n=>`${n.date} | ${n.topic}\n${n.text}`).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='目光-我的设计观察.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#theme').onclick=()=>{const dark=document.body.classList.contains('theme-dark')||(!document.body.classList.contains('theme-light')&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('theme-dark',!dark);document.body.classList.toggle('theme-light',dark);$('#theme').setAttribute('aria-label',dark?'切换到深色主题':'切换到浅色主题')};
